import TodoItem from './TodoItem.jsx'

const todos = [
  { id: 1, text: 'Buy milk', done: true },
  { id: 2, text: 'Walk the dog', done: false },
  { id: 3, text: 'Write the report', done: false },
]

function TodoList() {
  return (
    <ul>
      {todos.map(todo => (
        <TodoItem todo={todo} />
      ))}
    </ul>
  )
}

export default TodoList
